	/** @param list<PanelStudioDiagnostic> $diagnostics */
	private function auditWorkflow(array $node,string $path,array &$diagnostics):void{
		try{$p=$node['properties'];$workflow=WorkflowDefinition::make((string)$node['key'],isset($p['label'])?(string)$p['label']:null);$statePaths=[];foreach($node['children']as$index=>$child){if($child['kind']==='workflow_state'){$state=$this->workflowState($child);$workflow=$workflow->state($state);$statePaths[$state->name()]=$path.'.children['.$index.']';}}if(isset($p['initial_state'])){$workflow=$workflow->initial((string)$p['initial_state']);}foreach($node['children']as$child){if($child['kind']==='workflow_transition'){$workflow=$workflow->transition($this->workflowTransition($child));}}$workflow->assertValid();$analysis=(new PanelWorkflowSimulator())->analyze($workflow);if($p['require_terminal']&&$analysis->terminalStates()===[]){$diagnostics[]=new PanelStudioDiagnostic($path.'.children','workflow_terminal_state_missing','Studio workflows configured to require completion need at least one terminal state.');}foreach($analysis->unreachableStates()as$state){$diagnostics[]=new PanelStudioDiagnostic(($statePaths[$state]??$path).'.key','workflow_state_unreachable',"Workflow state '{$state}' cannot be reached from the initial state.");}foreach($analysis->statesWithoutTerminalPath()as$state){$diagnostics[]=new PanelStudioDiagnostic(($statePaths[$state]??$path).'.key','workflow_terminal_path_missing',"Workflow state '{$state}' has no path to a terminal state.");}}
