	/** @param list<PanelStudioDiagnostic> $diagnostics */
	private function auditBoard(array $node,string $path,array &$diagnostics):void{
		$statuses=[];$declared=[];$transitions=[];foreach($node['children']as$index=>$child){$properties=$child['properties'];$status=trim((string)($properties['status']??$child['key']));$normalized=Resource::normalizeName($status);$childPath=$path.'.children['.$index.']';if($normalized===''||isset($statuses[$normalized])){$diagnostics[]=new PanelStudioDiagnostic($childPath.'.properties.status','duplicate_board_status',isset($statuses[$normalized])?'Studio board columns must resolve to unique status values.':'Studio board-column status cannot normalize to an empty value.');}else{$statuses[$normalized]=$childPath;$declared[$status]=true;}if(($properties['accepts_moves']??true)===true){$transition=Resource::normalizeName((string)($properties['transition']??('move_to_'.$child['key'])));if($transition===''||isset($transitions[$transition])){$diagnostics[]=new PanelStudioDiagnostic($childPath.'.properties.transition','duplicate_board_transition',isset($transitions[$transition])?'Studio board move transitions must have unique names.':'Studio board move transition cannot normalize to an empty value.');}else{$transitions[$transition]=$childPath;}}}
